_UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400}

_TERM = r"\d+\s*(?:s(?:ecs?|econds?)?|m(?:ins?|inutes?)?|h(?:rs?|ours?)?|d(?:ays?)?)"
_FULL = re.compile(rf"\d+|{_TERM}(?:\s*{_TERM})*", re.I)
_PART = re.compile(r"(\d+)\s*([a-z]*)", re.I)


def parse_duration(text):
    """Parse a duration string like '1d 6h 30m', '90s', or '90' into seconds."""
    cleaned = text.strip()
    if not _FULL.fullmatch(cleaned):
        raise ValueError(f"could not parse duration: {text!r}")
    return sum(
        int(amount) * _UNITS[unit[:1].lower() or "s"]
        for amount, unit in _PART.findall(cleaned)
    )
