import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

_PART = re.compile(r"(\d+)\s*([a-z]+)")


def parse_duration(text):
    """Parse a duration string like '1d 6h 30m', '90s', or '90' into seconds."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")

    s = text.strip().lower()

    if re.fullmatch(r"\d+", s):
        return int(s)

    total = 0
    seen = set()
    pos = 0
    while pos < len(s):
        m = _PART.match(s, pos)
        if m is None:
            raise ValueError(f"invalid duration: {text!r}")
        count, unit = m.group(1), m.group(2)
        if unit not in _UNITS or _UNITS[unit] in seen:
            raise ValueError(f"invalid duration: {text!r}")
        seen.add(_UNITS[unit])
        total += int(count) * _UNITS[unit]
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1

    if not seen:
        raise ValueError(f"invalid duration: {text!r}")
    return total
```

Each `<number><unit>` chunk is consumed in order with optional whitespace between them, so `"1h30m"` and `"1d 6h 30m"` both work; a bare integer is treated as seconds. Repeating a unit (`"5m 3min"`) and any trailing junk are errors — the `ValueError` message echoes the original input verbatim.

