import re

_UNIT_SECONDS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

_PART = re.compile(r"(\d+)\s*([a-z]+)")


def parse_duration(text):
    """Parse a duration like "1d 6h 30m" into seconds; a bare number means seconds."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")

    s = text.strip().lower()
    if not s:
        raise ValueError(f"invalid duration: {text!r}")
    if s.isdigit():
        return int(s)

    total = 0
    pos = 0
    while pos < len(s):
        match = _PART.match(s, pos)
        if match is None or match.group(2) not in _UNIT_SECONDS:
            raise ValueError(f"invalid duration: {text!r}")
        total += int(match.group(1)) * _UNIT_SECONDS[match.group(2)]
        pos = match.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1

    return total
```

