import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

# Longest-first so "secs" doesn't match as "sec" + leftover junk.
_UNIT_ALT = "|".join(sorted(_UNITS, key=len, reverse=True))
_PART = rf"(\d+)\s*({_UNIT_ALT})"
_FULL = re.compile(rf"(?:{_PART}\s*)+$", re.IGNORECASE)
_PART_RE = re.compile(_PART, re.IGNORECASE)


def parse_duration(text):
    """Parse a duration string like "1d 6h 30m", "90s", or "90" into seconds."""
    if not isinstance(text, str):
        raise ValueError(f"cannot parse duration: {text!r}")

    cleaned = text.strip()
    if cleaned.isdigit():
        return int(cleaned)

    if not _FULL.match(cleaned):
        raise ValueError(f"cannot parse duration: {text!r}")

    return sum(
        int(amount) * _UNITS[unit.lower()]
        for amount, unit in _PART_RE.findall(cleaned)
    )
